34	module xgmii_baser_dec_64 #
35	(
36	    parameter DATA_WIDTH = 64,
37	    parameter CTRL_WIDTH = (DATA_WIDTH/8),
38	    parameter HDR_WIDTH = 2
39	)
40	(
41	    input  wire                  clk,
42	    input  wire                  rst,
43	
44	    /*
45	     * 10GBASE-R encoded input
46	     */
47	    input  wire [DATA_WIDTH-1:0] encoded_rx_data,
48	    input  wire [HDR_WIDTH-1:0]  encoded_rx_hdr,
49	
50	    /*
51	     * XGMII interface
52	     */
53	    output wire [DATA_WIDTH-1:0] xgmii_rxd,
54	    output wire [CTRL_WIDTH-1:0] xgmii_rxc,
55	
56	    /*
57	     * Status
58	     */
59	    output wire                  rx_bad_block,
60	    output wire                  rx_sequence_error
61	);
62	
63	// bus width assertions
64	initial begin
65	    if (DATA_WIDTH != 64) begin
66	        $error("Error: Interface width must be 64");
67	        $finish;
68	    end
69	
70	    if (CTRL_WIDTH * 8 != DATA_WIDTH) begin
71	        $error("Error: Interface requires byte (8-bit) granularity");
72	        $finish;
73	    end
74	
75	    if (HDR_WIDTH != 2) begin
76	        $error("Error: HDR_WIDTH must be 2");
77	        $finish;
78	    end
79	end
80	
81	localparam [7:0]
82	    XGMII_IDLE   = 8'h07,
83	    XGMII_LPI    = 8'h06,
84	    XGMII_START  = 8'hfb,
85	    XGMII_TERM   = 8'hfd,
86	    XGMII_ERROR  = 8'hfe,
87	    XGMII_SEQ_OS = 8'h9c,
88	    XGMII_RES_0  = 8'h1c,
89	    XGMII_RES_1  = 8'h3c,
90	    XGMII_RES_2  = 8'h7c,
91	    XGMII_RES_3  = 8'hbc,
92	    XGMII_RES_4  = 8'hdc,
93	    XGMII_RES_5  = 8'hf7,
94	    XGMII_SIG_OS = 8'h5c;
95	
96	localparam [6:0]
97	    CTRL_IDLE  = 7'h00,
98	    CTRL_LPI   = 7'h06,
99	    CTRL_ERROR = 7'h1e,
100	    CTRL_RES_0 = 7'h2d,
101	    CTRL_RES_1 = 7'h33,
102	    CTRL_RES_2 = 7'h4b,
103	    CTRL_RES_3 = 7'h55,
104	    CTRL_RES_4 = 7'h66,
105	    CTRL_RES_5 = 7'h78;
106	
107	localparam [3:0]
108	    O_SEQ_OS = 4'h0,
109	    O_SIG_OS = 4'hf;
110	
111	localparam [1:0]
112	    SYNC_DATA = 2'b10,
113	    SYNC_CTRL = 2'b01;
114	
115	localparam [7:0]
116	    BLOCK_TYPE_CTRL     = 8'h1e, // C7 C6 C5 C4 C3 C2 C1 C0 BT
117	    BLOCK_TYPE_OS_4     = 8'h2d, // D7 D6 D5 O4 C3 C2 C1 C0 BT
118	    BLOCK_TYPE_START_4  = 8'h33, // D7 D6 D5    C3 C2 C1 C0 BT
119	    BLOCK_TYPE_OS_START = 8'h66, // D7 D6 D5    O0 D3 D2 D1 BT
120	    BLOCK_TYPE_OS_04    = 8'h55, // D7 D6 D5 O4 O0 D3 D2 D1 BT
121	    BLOCK_TYPE_START_0  = 8'h78, // D7 D6 D5 D4 D3 D2 D1    BT
122	    BLOCK_TYPE_OS_0     = 8'h4b, // C7 C6 C5 C4 O0 D3 D2 D1 BT
123	    BLOCK_TYPE_TERM_0   = 8'h87, // C7 C6 C5 C4 C3 C2 C1    BT
124	    BLOCK_TYPE_TERM_1   = 8'h99, // C7 C6 C5 C4 C3 C2    D0 BT
125	    BLOCK_TYPE_TERM_2   = 8'haa, // C7 C6 C5 C4 C3    D1 D0 BT
126	    BLOCK_TYPE_TERM_3   = 8'hb4, // C7 C6 C5 C4    D2 D1 D0 BT
127	    BLOCK_TYPE_TERM_4   = 8'hcc, // C7 C6 C5    D3 D2 D1 D0 BT
128	    BLOCK_TYPE_TERM_5   = 8'hd2, // C7 C6    D4 D3 D2 D1 D0 BT
129	    BLOCK_TYPE_TERM_6   = 8'he1, // C7    D5 D4 D3 D2 D1 D0 BT
130	    BLOCK_TYPE_TERM_7   = 8'hff; //    D6 D5 D4 D3 D2 D1 D0 BT
131	
132	reg [DATA_WIDTH-1:0] decoded_ctrl;
133	reg [CTRL_WIDTH-1:0] decode_err;
134	
135	reg [DATA_WIDTH-1:0] xgmii_rxd_reg = {DATA_WIDTH{1'b0}}, xgmii_rxd_next;
136	reg [CTRL_WIDTH-1:0] xgmii_rxc_reg = {CTRL_WIDTH{1'b0}}, xgmii_rxc_next;
137	
138	reg rx_bad_block_reg = 1'b0, rx_bad_block_next;
139	reg rx_sequence_error_reg = 1'b0, rx_sequence_error_next;
140	reg frame_reg = 1'b0, frame_next;
141	
142	assign xgmii_rxd = xgmii_rxd_reg;
143	assign xgmii_rxc = xgmii_rxc_reg;
144	
145	assign rx_bad_block = rx_bad_block_reg;
146	assign rx_sequence_error = rx_sequence_error_reg;
147	
148	integer i;
149	
150	always @* begin
151	    xgmii_rxd_next = {8{XGMII_ERROR}};
152	    xgmii_rxc_next = 8'hff;
153	    rx_bad_block_next = 1'b0;
154	    rx_sequence_error_next = 1'b0;
155	    frame_next = frame_reg;
156	
157	    for (i = 0; i < CTRL_WIDTH; i = i + 1) begin
158	        case (encoded_rx_data[7*i+8 +: 7])
159	            CTRL_IDLE: begin
160	                decoded_ctrl[8*i +: 8] = XGMII_IDLE;
161	                decode_err[i] = 1'b0;
162	            end
163	            CTRL_LPI: begin
164	                decoded_ctrl[8*i +: 8] = XGMII_LPI;
165	                decode_err[i] = 1'b0;
166	            end
167	            CTRL_ERROR: begin
168	                decoded_ctrl[8*i +: 8] = XGMII_ERROR;
169	                decode_err[i] = 1'b0;
170	            end
171	            CTRL_RES_0: begin
172	                decoded_ctrl[8*i +: 8] = XGMII_RES_0;
173	                decode_err[i] = 1'b0;
174	            end
175	            CTRL_RES_1: begin
176	                decoded_ctrl[8*i +: 8] = XGMII_RES_1;
177	                decode_err[i] = 1'b0;
178	            end
179	            CTRL_RES_2: begin
180	                decoded_ctrl[8*i +: 8] = XGMII_RES_2;
181	                decode_err[i] = 1'b0;
182	            end
183	            CTRL_RES_3: begin
184	                decoded_ctrl[8*i +: 8] = XGMII_RES_3;
185	                decode_err[i] = 1'b0;
186	            end
187	            CTRL_RES_4: begin
188	                decoded_ctrl[8*i +: 8] = XGMII_RES_4;
189	                decode_err[i] = 1'b0;
190	            end
191	            CTRL_RES_5: begin
192	                decoded_ctrl[8*i +: 8] = XGMII_RES_5;
193	                decode_err[i] = 1'b0;
194	            end
195	            default: begin
196	                decoded_ctrl[8*i +: 8] = XGMII_ERROR;
197	                decode_err[i] = 1'b1;
198	            end
199	        endcase
200	    end
201	
202	    // use only four bits of block type for reduced fanin
203	    if (encoded_rx_hdr[0] == 0) begin
204	        xgmii_rxd_next = encoded_rx_data;
205	        xgmii_rxc_next = 8'h00;
206	        rx_bad_block_next = 1'b0;
207	    end else begin
208	        case (encoded_rx_data[7:4])
209	            BLOCK_TYPE_CTRL[7:4]: begin
210	                // C7 C6 C5 C4 C3 C2 C1 C0 BT
211	                xgmii_rxd_next = decoded_ctrl;
212	                xgmii_rxc_next = 8'hff;
213	                rx_bad_block_next = decode_err != 0;
214	            end
215	            BLOCK_TYPE_OS_4[7:4]: begin
216	                // D7 D6 D5 O4 C3 C2 C1 C0 BT
217	                xgmii_rxd_next[31:0] = decoded_ctrl[31:0];
218	                xgmii_rxc_next[3:0] = 4'hf;
219	                xgmii_rxd_next[63:40] = encoded_rx_data[63:40];
220	                xgmii_rxc_next[7:4] = 4'h1;
221	                if (encoded_rx_data[39:36] == O_SEQ_OS) begin
222	                    xgmii_rxd_next[39:32] = XGMII_SEQ_OS;
223	                    rx_bad_block_next = decode_err[3:0] != 0;
224	                end else begin
225	                    xgmii_rxd_next[39:32] = XGMII_ERROR;
226	                    rx_bad_block_next = 1'b1;
227	                end
228	            end
229	            BLOCK_TYPE_START_4[7:4]: begin
230	                // D7 D6 D5    C3 C2 C1 C0 BT
231	                xgmii_rxd_next = {encoded_rx_data[63:40], XGMII_START, decoded_ctrl[31:0]};
232	                xgmii_rxc_next = 8'h1f;
233	                rx_bad_block_next = decode_err[3:0] != 0;
234	                rx_sequence_error_next = frame_reg;
235	                frame_next = 1'b1;
236	            end
237	            BLOCK_TYPE_OS_START[7:4]: begin
238	                // D7 D6 D5    O0 D3 D2 D1 BT
239	                xgmii_rxd_next[31:8] = encoded_rx_data[31:8];
240	                xgmii_rxc_next[3:0] = 4'hf;
241	                if (encoded_rx_data[35:32] == O_SEQ_OS) begin
242	                    xgmii_rxd_next[7:0] = XGMII_SEQ_OS;
243	                    rx_bad_block_next = 1'b0;
244	                end else begin
245	                    xgmii_rxd_next[7:0] = XGMII_ERROR;
246	                    rx_bad_block_next = 1'b1;
247	                end
248	                xgmii_rxd_next[63:32] = {encoded_rx_data[63:40], XGMII_START};
249	                xgmii_rxc_next[7:4] = 4'h1;
250	                rx_sequence_error_next = frame_reg;
251	                frame_next = 1'b1;
252	            end
253	            BLOCK_TYPE_OS_04[7:4]: begin
254	                // D7 D6 D5 O4 O0 D3 D2 D1 BT
255	                rx_bad_block_next = 1'b0;
256	                xgmii_rxd_next[31:8] = encoded_rx_data[31:8];
257	                xgmii_rxc_next[3:0] = 4'h1;
258	                if (encoded_rx_data[35:32] == O_SEQ_OS) begin
259	                    xgmii_rxd_next[7:0] = XGMII_SEQ_OS;
260	                end else begin
261	                    xgmii_rxd_next[7:0] = XGMII_ERROR;
262	                    rx_bad_block_next = 1'b1;
263	                end
264	                xgmii_rxd_next[63:40] = encoded_rx_data[63:40];
265	                xgmii_rxc_next[7:4] = 4'h1;
266	                if (encoded_rx_data[39:36] == O_SEQ_OS) begin
267	                    xgmii_rxd_next[39:32] = XGMII_SEQ_OS;
268	                end else begin
269	                    xgmii_rxd_next[39:32] = XGMII_ERROR;
270	                    rx_bad_block_next = 1'b1;
271	                end
272	            end
273	            BLOCK_TYPE_START_0[7:4]: begin
274	                // D7 D6 D5 D4 D3 D2 D1    BT
275	                xgmii_rxd_next = {encoded_rx_data[63:8], XGMII_START};
276	                xgmii_rxc_next = 8'h01;
277	                rx_bad_block_next = 1'b0;
278	                rx_sequence_error_next = frame_reg;
279	                frame_next = 1'b1;
280	            end
281	            BLOCK_TYPE_OS_0[7:4]: begin
282	                // C7 C6 C5 C4 O0 D3 D2 D1 BT
283	                xgmii_rxd_next[31:8] = encoded_rx_data[31:8];
284	                xgmii_rxc_next[3:0] = 4'h1;
285	                if (encoded_rx_data[35:32] == O_SEQ_OS) begin
286	                    xgmii_rxd_next[7:0] = XGMII_SEQ_OS;
287	                    rx_bad_block_next = decode_err[7:4] != 0;
288	                end else begin
289	                    xgmii_rxd_next[7:0] = XGMII_ERROR;
290	                    rx_bad_block_next = 1'b1;
291	                end
292	                xgmii_rxd_next[63:32] = decoded_ctrl[63:32];
293	                xgmii_rxc_next[7:4] = 4'hf;
294	            end
295	            BLOCK_TYPE_TERM_0[7:4]: begin
296	                // C7 C6 C5 C4 C3 C2 C1    BT
297	                xgmii_rxd_next = {decoded_ctrl[63:8], XGMII_TERM};
298	                xgmii_rxc_next = 8'hff;
299	                rx_bad_block_next = decode_err[7:1] != 0;
300	                rx_sequence_error_next = !frame_reg;
301	                frame_next = 1'b0;
302	            end
303	            BLOCK_TYPE_TERM_1[7:4]: begin
304	                // C7 C6 C5 C4 C3 C2    D0 BT
305	                xgmii_rxd_next = {decoded_ctrl[63:16], XGMII_TERM, encoded_rx_data[15:8]};
306	                xgmii_rxc_next = 8'hfe;
307	                rx_bad_block_next = decode_err[7:2] != 0;
308	                rx_sequence_error_next = !frame_reg;
309	                frame_next = 1'b0;
310	            end
311	            BLOCK_TYPE_TERM_2[7:4]: begin
312	                // C7 C6 C5 C4 C3    D1 D0 BT
313	                xgmii_rxd_next = {decoded_ctrl[63:24], XGMII_TERM, encoded_rx_data[23:8]};
314	                xgmii_rxc_next = 8'hfc;
315	                rx_bad_block_next = decode_err[7:3] != 0;
316	                rx_sequence_error_next = !frame_reg;
317	                frame_next = 1'b0;
318	            end
319	            BLOCK_TYPE_TERM_3[7:4]: begin
320	                // C7 C6 C5 C4    D2 D1 D0 BT
321	                xgmii_rxd_next = {decoded_ctrl[63:32], XGMII_TERM, encoded_rx_data[31:8]};
322	                xgmii_rxc_next = 8'hf8;
323	                rx_bad_block_next = decode_err[7:4] != 0;
324	                rx_sequence_error_next = !frame_reg;
325	                frame_next = 1'b0;
326	            end
327	            BLOCK_TYPE_TERM_4[7:4]: begin
328	                // C7 C6 C5    D3 D2 D1 D0 BT
329	                xgmii_rxd_next = {decoded_ctrl[63:40], XGMII_TERM, encoded_rx_data[39:8]};
330	                xgmii_rxc_next = 8'hf0;
331	                rx_bad_block_next = decode_err[7:5] != 0;
332	                rx_sequence_error_next = !frame_reg;
333	                frame_next = 1'b0;
334	            end
335	            BLOCK_TYPE_TERM_5[7:4]: begin
336	                // C7 C6    D4 D3 D2 D1 D0 BT
337	                xgmii_rxd_next = {decoded_ctrl[63:48], XGMII_TERM, encoded_rx_data[47:8]};
338	                xgmii_rxc_next = 8'he0;
339	                rx_bad_block_next = decode_err[7:6] != 0;
340	                rx_sequence_error_next = !frame_reg;
341	                frame_next = 1'b0;
342	            end
343	            BLOCK_TYPE_TERM_6[7:4]: begin
344	                // C7    D5 D4 D3 D2 D1 D0 BT
345	                xgmii_rxd_next = {decoded_ctrl[63:56], XGMII_TERM, encoded_rx_data[55:8]};
346	                xgmii_rxc_next = 8'hc0;
347	                rx_bad_block_next = decode_err[7] != 0;
348	                rx_sequence_error_next = !frame_reg;
349	                frame_next = 1'b0;
350	            end
351	            BLOCK_TYPE_TERM_7[7:4]: begin
352	                //    D6 D5 D4 D3 D2 D1 D0 BT
353	                xgmii_rxd_next = {XGMII_TERM, encoded_rx_data[63:8]};
354	                xgmii_rxc_next = 8'h80;
355	                rx_bad_block_next = 1'b0;
356	                rx_sequence_error_next = !frame_reg;
357	                frame_next = 1'b0;
358	            end
359	            default: begin
360	                // invalid block type
361	                xgmii_rxd_next = {8{XGMII_ERROR}};
362	                xgmii_rxc_next = 8'hff;
363	                rx_bad_block_next = 1'b1;
364	            end
365	        endcase
366	    end
367	
368	    // check all block type bits to detect bad encodings
369	    if (encoded_rx_hdr == SYNC_DATA) begin
370	    end else if (encoded_rx_hdr == SYNC_CTRL) begin
371	        case (encoded_rx_data[7:0])
372	            BLOCK_TYPE_CTRL: begin end
373	            BLOCK_TYPE_OS_4: begin end
374	            BLOCK_TYPE_START_4: begin end
375	            BLOCK_TYPE_OS_START: begin end
376	            BLOCK_TYPE_OS_04: begin end
377	            BLOCK_TYPE_START_0: begin end
378	            BLOCK_TYPE_OS_0: begin end
379	            BLOCK_TYPE_TERM_0: begin end
380	            BLOCK_TYPE_TERM_1: begin end
381	            BLOCK_TYPE_TERM_2: begin end
382	            BLOCK_TYPE_TERM_3: begin end
383	            BLOCK_TYPE_TERM_4: begin end
384	            BLOCK_TYPE_TERM_5: begin end
385	            BLOCK_TYPE_TERM_6: begin end
386	            BLOCK_TYPE_TERM_7: begin end
387	            default: begin
388	                // invalid block type
389	                xgmii_rxd_next = {8{XGMII_ERROR}};
390	                xgmii_rxc_next = 8'hff;
391	                rx_bad_block_next = 1'b1;
392	            end
393	        endcase
394	    end else begin
395	        // invalid header
396	        xgmii_rxd_next = {8{XGMII_ERROR}};
397	        xgmii_rxc_next = 8'hff;
398	        rx_bad_block_next = 1'b1;
399	    end
400	end
401	
402	always @(posedge clk) begin
403	    xgmii_rxd_reg <= xgmii_rxd_next;
404	    xgmii_rxc_reg <= xgmii_rxc_next;
405	
406	    rx_bad_block_reg <= rx_bad_block_next;
407	    rx_sequence_error_reg <= rx_sequence_error_next;
408	    frame_reg <= frame_next;
409	
410	    if (rst) begin
411	        frame_reg <= 1'b0;
412	    end
413	end
414	
415	endmodule
416	
417	`resetall
