150	    INPUT_TYPE_START_4 = 4'd3,
151	    INPUT_TYPE_DATA = 4'd4,
152	    INPUT_TYPE_TERM_0 = 4'd8,
153	    INPUT_TYPE_TERM_1 = 4'd9,
