207	assign crc_valid[7] = crc_next == ~32'h2144df1c;
208	assign crc_valid[6] = crc_next == ~32'hc622f71d;
209	assign crc_valid[5] = crc_next == ~32'hb1c2a1a3;
210	assign crc_valid[4] = crc_next == ~32'h9d6cdf7e;
211	assign crc_valid[3] = crc_next == ~32'h6522df69;
212	assign crc_valid[2] = crc_next == ~32'he60914ae;
