246	// Mask input data
247	integer j;
248	
249	always @* begin
250	    // minimal checks of control info to simplify datapath logic, full checks performed later
251	    if (encoded_rx_hdr[0] == 0) begin
252	        encoded_rx_data_masked = encoded_rx_data;
253	    end else if (encoded_rx_data[7]) begin
254	        // terminate
255	        case (encoded_rx_data[6:4])
256	            3'd0: encoded_rx_data_masked = 64'd0;
257	            3'd1: encoded_rx_data_masked = {56'd0, encoded_rx_data[15:8]};
258	            3'd2: encoded_rx_data_masked = {48'd0, encoded_rx_data[23:8]};
259	            3'd3: encoded_rx_data_masked = {40'd0, encoded_rx_data[31:8]};
260	            3'd4: encoded_rx_data_masked = {32'd0, encoded_rx_data[39:8]};
261	            3'd5: encoded_rx_data_masked = {24'd0, encoded_rx_data[47:8]};
262	            3'd6: encoded_rx_data_masked = {16'd0, encoded_rx_data[55:8]};
263	            3'd7: encoded_rx_data_masked = {8'd0, encoded_rx_data[63:8]};
264	        endcase
265	    end else begin
266	        // start, OS, etc.
267	        encoded_rx_data_masked = {encoded_rx_data[63:8], 8'd0};
268	    end
269	end
270	
271	always @* begin
272	    state_next = STATE_IDLE;
273	
274	    reset_crc = 1'b0;
275	
276	    m_axis_tdata_next = input_data_d1;
277	    m_axis_tkeep_next = 8'd0;
278	    m_axis_tvalid_next = 1'b0;
279	    m_axis_tlast_next = 1'b0;
280	    m_axis_tuser_next = m_axis_tuser_reg;
281	    m_axis_tuser_next[0] = 1'b0;
282	
283	    error_bad_frame_next = 1'b0;
284	    error_bad_fcs_next = 1'b0;
285	
286	    case (state_reg)
287	        STATE_IDLE: begin
288	            // idle state - wait for packet
289	            reset_crc = 1'b1;
290	
291	            if (input_type_d1 == INPUT_TYPE_START_0 && cfg_rx_enable) begin
292	                // start condition
293	                reset_crc = 1'b0;
294	                state_next = STATE_PAYLOAD;
295	            end else begin
296	                state_next = STATE_IDLE;
297	            end
298	        end
299	        STATE_PAYLOAD: begin
300	            // read payload
301	            m_axis_tdata_next = input_data_d1;
302	            m_axis_tkeep_next = 8'hff;
303	            m_axis_tvalid_next = 1'b1;
304	            m_axis_tlast_next = 1'b0;
305	            m_axis_tuser_next[0] = 1'b0;
306	
307	            if (input_type_d0[3]) begin
308	                // INPUT_TYPE_TERM_*
309	                reset_crc = 1'b1;
310	            end
311	
312	            if (PTP_TS_ENABLE) begin
313	                m_axis_tuser_next[1 +: PTP_TS_WIDTH] = (!PTP_TS_FMT_TOD || ptp_ts_borrow_reg) ? ptp_ts_reg : ptp_ts_adj_reg;
314	            end
315	
316	            if (input_type_d0 == INPUT_TYPE_DATA) begin
317	                state_next = STATE_PAYLOAD;
318	            end else if (input_type_d0[3]) begin
319	                // INPUT_TYPE_TERM_*
320	                if (input_type_d0 <= INPUT_TYPE_TERM_4) begin
321	                    // end this cycle
322	                    case (input_type_d0)
323	                        INPUT_TYPE_TERM_0: m_axis_tkeep_next = 8'b00001111;
324	                        INPUT_TYPE_TERM_1: m_axis_tkeep_next = 8'b00011111;
325	                        INPUT_TYPE_TERM_2: m_axis_tkeep_next = 8'b00111111;
326	                        INPUT_TYPE_TERM_3: m_axis_tkeep_next = 8'b01111111;
327	                        INPUT_TYPE_TERM_4: m_axis_tkeep_next = 8'b11111111;
328	                    endcase
329	                    m_axis_tlast_next = 1'b1;
330	                    if ((input_type_d0 == INPUT_TYPE_TERM_0 && crc_valid_save[7]) ||
331	                        (input_type_d0 == INPUT_TYPE_TERM_1 && crc_valid[0]) ||
332	                        (input_type_d0 == INPUT_TYPE_TERM_2 && crc_valid[1]) ||
333	                        (input_type_d0 == INPUT_TYPE_TERM_3 && crc_valid[2]) ||
334	                        (input_type_d0 == INPUT_TYPE_TERM_4 && crc_valid[3])) begin
335	                        // CRC valid
336	                    end else begin
337	                        m_axis_tuser_next[0] = 1'b1;
338	                        error_bad_frame_next = 1'b1;
339	                        error_bad_fcs_next = 1'b1;
340	                    end
341	                    state_next = STATE_IDLE;
342	                end else begin
343	                    // need extra cycle
344	                    state_next = STATE_LAST;
345	                end
346	            end else begin
347	                // control or error characters in packet
348	                m_axis_tlast_next = 1'b1;
349	                m_axis_tuser_next[0] = 1'b1;
350	                error_bad_frame_next = 1'b1;
351	                reset_crc = 1'b1;
352	                state_next = STATE_IDLE;
353	            end
354	        end
355	        STATE_LAST: begin
356	            // last cycle of packet
357	            m_axis_tdata_next = input_data_d1;
358	            m_axis_tkeep_next = 8'hff;
359	            m_axis_tvalid_next = 1'b1;
360	            m_axis_tlast_next = 1'b1;
361	            m_axis_tuser_next[0] = 1'b0;
362	
363	            reset_crc = 1'b1;
364	
365	            case (input_type_d1)
366	                INPUT_TYPE_TERM_5: m_axis_tkeep_next = 8'b00000001;
367	                INPUT_TYPE_TERM_6: m_axis_tkeep_next = 8'b00000011;
368	                INPUT_TYPE_TERM_7: m_axis_tkeep_next = 8'b00000111;
369	            endcase
370	
371	            if ((input_type_d1 == INPUT_TYPE_TERM_5 && crc_valid_save[4]) ||
372	                (input_type_d1 == INPUT_TYPE_TERM_6 && crc_valid_save[5]) ||
373	                (input_type_d1 == INPUT_TYPE_TERM_7 && crc_valid_save[6])) begin
374	                // CRC valid
375	            end else begin
376	                m_axis_tuser_next[0] = 1'b1;
377	                error_bad_frame_next = 1'b1;
378	                error_bad_fcs_next = 1'b1;
379	            end
380	
381	            state_next = STATE_IDLE;
382	        end
383	    endcase
384	end
385	
386	always @(posedge clk) begin
387	    state_reg <= state_next;
388	
389	    m_axis_tdata_reg <= m_axis_tdata_next;
390	    m_axis_tkeep_reg <= m_axis_tkeep_next;
391	    m_axis_tvalid_reg <= m_axis_tvalid_next;
392	    m_axis_tlast_reg <= m_axis_tlast_next;
393	    m_axis_tuser_reg <= m_axis_tuser_next;
394	
395	    start_packet_reg <= 2'b00;
396	    error_bad_frame_reg <= error_bad_frame_next;
397	    error_bad_fcs_reg <= error_bad_fcs_next;
398	    rx_bad_block_reg <= 1'b0;
399	
400	    delay_type_valid <= 1'b0;
401	
402	    swap_data <= encoded_rx_data_masked[63:32];
403	
404	    if (PTP_TS_ENABLE && PTP_TS_FMT_TOD) begin
405	        // ns field rollover
406	        ptp_ts_adj_reg[15:0] <= ptp_ts_reg[15:0];
407	        {ptp_ts_borrow_reg, ptp_ts_adj_reg[45:16]} <= $signed({1'b0, ptp_ts_reg[45:16]}) - $signed(31'd1000000000);
408	        ptp_ts_adj_reg[47:46] <= 0;
409	        ptp_ts_adj_reg[95:48] <= ptp_ts_reg[95:48] + 1;
410	    end
411	
412	    if (encoded_rx_hdr == SYNC_CTRL && encoded_rx_data[7:0] == BLOCK_TYPE_START_0) begin
413	        lanes_swapped <= 1'b0;
414	        input_type_d0 <= INPUT_TYPE_START_0;
415	        input_data_d0 <= encoded_rx_data_masked;
416	    end else if (encoded_rx_hdr == SYNC_CTRL && (encoded_rx_data[7:0] == BLOCK_TYPE_START_4 || encoded_rx_data[7:0] == BLOCK_TYPE_OS_START)) begin
417	        lanes_swapped <= 1'b1;
418	        delay_type_valid <= 1'b1;
419	
420	        if (delay_type_valid) begin
421	            input_type_d0 <= delay_type;
422	        end else begin
423	            input_type_d0 <= INPUT_TYPE_IDLE;
424	        end
425	        input_data_d0 <= {encoded_rx_data_masked[31:0], swap_data};
426	    end else if (lanes_swapped) begin
427	        if (delay_type_valid) begin
428	            input_type_d0 <= delay_type;
429	        end else if (encoded_rx_hdr == SYNC_DATA) begin
430	            input_type_d0 <= INPUT_TYPE_DATA;
431	        end else if (encoded_rx_hdr == SYNC_CTRL) begin
432	            case (encoded_rx_data[7:0])
433	                BLOCK_TYPE_TERM_0: input_type_d0 <= INPUT_TYPE_TERM_4;
434	                BLOCK_TYPE_TERM_1: input_type_d0 <= INPUT_TYPE_TERM_5;
435	                BLOCK_TYPE_TERM_2: input_type_d0 <= INPUT_TYPE_TERM_6;
436	                BLOCK_TYPE_TERM_3: input_type_d0 <= INPUT_TYPE_TERM_7;
437	                BLOCK_TYPE_TERM_4: begin
438	                    delay_type_valid <= 1'b1;
439	                    input_type_d0 <= INPUT_TYPE_DATA;
440	                end
441	                BLOCK_TYPE_TERM_5: begin
442	                    delay_type_valid <= 1'b1;
443	                    input_type_d0 <= INPUT_TYPE_DATA;
444	                end
445	                BLOCK_TYPE_TERM_6: begin
446	                    delay_type_valid <= 1'b1;
447	                    input_type_d0 <= INPUT_TYPE_DATA;
448	                end
449	                BLOCK_TYPE_TERM_7: begin
450	                    delay_type_valid <= 1'b1;
451	                    input_type_d0 <= INPUT_TYPE_DATA;
452	                end
453	                default: begin
454	                    rx_bad_block_reg <= 1'b1;
455	                    input_type_d0 <= INPUT_TYPE_ERROR;
456	                end
457	            endcase
458	        end else begin
459	            rx_bad_block_reg <= 1'b1;
460	            input_type_d0 <= INPUT_TYPE_ERROR;
461	        end
462	        input_data_d0 <= {encoded_rx_data_masked[31:0], swap_data};
463	    end else begin
464	        if (encoded_rx_hdr == SYNC_DATA) begin
465	            input_type_d0 <= INPUT_TYPE_DATA;
466	        end else if (encoded_rx_hdr == SYNC_CTRL) begin
467	            case (encoded_rx_data[7:0])
468	                BLOCK_TYPE_TERM_0: input_type_d0 <= INPUT_TYPE_TERM_0;
469	                BLOCK_TYPE_TERM_1: input_type_d0 <= INPUT_TYPE_TERM_1;
470	                BLOCK_TYPE_TERM_2: input_type_d0 <= INPUT_TYPE_TERM_2;
471	                BLOCK_TYPE_TERM_3: input_type_d0 <= INPUT_TYPE_TERM_3;
472	                BLOCK_TYPE_TERM_4: input_type_d0 <= INPUT_TYPE_TERM_4;
473	                BLOCK_TYPE_TERM_5: input_type_d0 <= INPUT_TYPE_TERM_5;
474	                BLOCK_TYPE_TERM_6: input_type_d0 <= INPUT_TYPE_TERM_6;
475	                BLOCK_TYPE_TERM_7: input_type_d0 <= INPUT_TYPE_TERM_7;
476	                default: begin
477	                    rx_bad_block_reg <= 1'b1;
478	                    input_type_d0 <= INPUT_TYPE_ERROR;
479	                end
480	            endcase
481	        end else begin
482	            rx_bad_block_reg <= 1'b1;
483	            input_type_d0 <= INPUT_TYPE_ERROR;
484	        end
485	        input_data_d0 <= encoded_rx_data_masked;
486	    end
487	
488	    if (encoded_rx_hdr == SYNC_DATA) begin
489	        delay_type <= INPUT_TYPE_DATA;
490	    end else if (encoded_rx_hdr == SYNC_CTRL) begin
491	        case (encoded_rx_data[7:0])
492	            BLOCK_TYPE_START_4: delay_type <= INPUT_TYPE_START_0;
493	            BLOCK_TYPE_TERM_0: delay_type <= INPUT_TYPE_TERM_4;
494	            BLOCK_TYPE_TERM_1: delay_type <= INPUT_TYPE_TERM_5;
495	            BLOCK_TYPE_TERM_2: delay_type <= INPUT_TYPE_TERM_6;
496	            BLOCK_TYPE_TERM_3: delay_type <= INPUT_TYPE_TERM_7;
497	            BLOCK_TYPE_TERM_4: delay_type <= INPUT_TYPE_TERM_0;
498	            BLOCK_TYPE_TERM_5: delay_type <= INPUT_TYPE_TERM_1;
499	            BLOCK_TYPE_TERM_6: delay_type <= INPUT_TYPE_TERM_2;
500	            BLOCK_TYPE_TERM_7: delay_type <= INPUT_TYPE_TERM_3;
501	            default: delay_type <= INPUT_TYPE_ERROR;
502	        endcase
503	    end else begin
504	        delay_type <= INPUT_TYPE_ERROR;
505	    end
506	
507	    if (delay_type == INPUT_TYPE_START_0 && delay_type_valid) begin
508	        start_packet_reg <= 2'b10;
509	        if (PTP_TS_FMT_TOD) begin
510	            ptp_ts_reg[45:0] <= ptp_ts[45:0] + (ts_inc_reg >> 1);
511	            ptp_ts_reg[95:48] <= ptp_ts[95:48];
512	        end else begin
513	            ptp_ts_reg <= ptp_ts + (ts_inc_reg >> 1);
514	        end
515	    end
516	
517	    if (input_type_d0 == INPUT_TYPE_START_0) begin
518	        if (!lanes_swapped) begin
519	            start_packet_reg <= 2'b01;
520	            ptp_ts_reg <= ptp_ts;
521	        end
522	    end
523	
524	    input_type_d1 <= input_type_d0;
525	    input_data_d1 <= input_data_d0;
526	
527	    if (reset_crc) begin
528	        crc_state <= 32'hFFFFFFFF;
529	    end else begin
530	        crc_state <= crc_next;
531	    end
532	
533	    crc_valid_save <= crc_valid;
534	
535	    last_ts_reg <= ptp_ts;
536	    ts_inc_reg <= ptp_ts - last_ts_reg;
537	
538	    if (rst) begin
539	        state_reg <= STATE_IDLE;
540	
541	        m_axis_tvalid_reg <= 1'b0;
542	
543	        start_packet_reg <= 2'b00;
544	        error_bad_frame_reg <= 1'b0;
545	        error_bad_fcs_reg <= 1'b0;
546	        rx_bad_block_reg <= 1'b0;
547	
548	        input_type_d0 <= INPUT_TYPE_IDLE;
549	        input_type_d1 <= INPUT_TYPE_IDLE;
550	
551	        lanes_swapped <= 1'b0;
552	
553	        delay_type_valid <= 1'b0;
554	        delay_type <= INPUT_TYPE_IDLE;
555	    end
556	end
557	
558	endmodule
