31	/*
32	 * AXI4-Stream 10GBASE-R frame transmitter (AXI in, 10GBASE-R out)
33	 */
34	module axis_baser_tx_64 #
35	(
36	    parameter DATA_WIDTH = 64,
37	    parameter KEEP_WIDTH = (DATA_WIDTH/8),
38	    parameter HDR_WIDTH = 2,
39	    parameter ENABLE_PADDING = 1,
40	    parameter ENABLE_DIC = 1,
41	    parameter MIN_FRAME_LENGTH = 64,
42	    parameter PTP_TS_ENABLE = 0,
43	    parameter PTP_TS_FMT_TOD = 1,
44	    parameter PTP_TS_WIDTH = PTP_TS_FMT_TOD ? 96 : 64,
45	    parameter PTP_TS_CTRL_IN_TUSER = 0,
46	    parameter PTP_TAG_ENABLE = PTP_TS_ENABLE,
47	    parameter PTP_TAG_WIDTH = 16,
48	    parameter USER_WIDTH = (PTP_TS_ENABLE ? (PTP_TAG_ENABLE ? PTP_TAG_WIDTH : 0) + (PTP_TS_CTRL_IN_TUSER ? 1 : 0) : 0) + 1
49	)
50	(
51	    input  wire                      clk,
52	    input  wire                      rst,
53	
54	    /*
55	     * AXI input
56	     */
57	    input  wire [DATA_WIDTH-1:0]     s_axis_tdata,
58	    input  wire [KEEP_WIDTH-1:0]     s_axis_tkeep,
59	    input  wire                      s_axis_tvalid,
60	    output wire                      s_axis_tready,
61	    input  wire                      s_axis_tlast,
62	    input  wire [USER_WIDTH-1:0]     s_axis_tuser,
63	
64	    /*
65	     * 10GBASE-R encoded interface
66	     */
67	    output wire [DATA_WIDTH-1:0]     encoded_tx_data,
68	    output wire [HDR_WIDTH-1:0]      encoded_tx_hdr,
69	
70	    /*
71	     * PTP
72	     */
73	    input  wire [PTP_TS_WIDTH-1:0]   ptp_ts,
74	    output wire [PTP_TS_WIDTH-1:0]   m_axis_ptp_ts,
75	    output wire [PTP_TAG_WIDTH-1:0]  m_axis_ptp_ts_tag,
76	    output wire                      m_axis_ptp_ts_valid,
77	
78	    /*
79	     * Configuration
80	     */
81	    input  wire [7:0]                cfg_ifg,
82	    input  wire                      cfg_tx_enable,
83	
84	    /*
85	     * Status
86	     */
87	    output wire [1:0]                start_packet,
88	    output wire                      error_underflow
89	);
90	
91	parameter EMPTY_WIDTH = $clog2(KEEP_WIDTH);
92	parameter MIN_LEN_WIDTH = $clog2(MIN_FRAME_LENGTH-4-KEEP_WIDTH+1);
93	
94	// bus width assertions
95	initial begin
96	    if (DATA_WIDTH != 64) begin
97	        $error("Error: Interface width must be 64");
98	        $finish;
99	    end
100	
101	    if (KEEP_WIDTH * 8 != DATA_WIDTH) begin
102	        $error("Error: Interface requires byte (8-bit) granularity");
103	        $finish;
104	    end
105	
106	    if (HDR_WIDTH != 2) begin
107	        $error("Error: HDR_WIDTH must be 2");
108	        $finish;
109	    end
110	end
111	
112	localparam [7:0]
113	    ETH_PRE = 8'h55,
114	    ETH_SFD = 8'hD5;
115	
116	localparam [6:0]
117	    CTRL_IDLE  = 7'h00,
118	    CTRL_LPI   = 7'h06,
119	    CTRL_ERROR = 7'h1e,
120	    CTRL_RES_0 = 7'h2d,
121	    CTRL_RES_1 = 7'h33,
122	    CTRL_RES_2 = 7'h4b,
123	    CTRL_RES_3 = 7'h55,
124	    CTRL_RES_4 = 7'h66,
125	    CTRL_RES_5 = 7'h78;
126	
127	localparam [3:0]
128	    O_SEQ_OS = 4'h0,
129	    O_SIG_OS = 4'hf;
130	
131	localparam [1:0]
132	    SYNC_DATA = 2'b10,
133	    SYNC_CTRL = 2'b01;
134	
135	localparam [7:0]
136	    BLOCK_TYPE_CTRL     = 8'h1e, // C7 C6 C5 C4 C3 C2 C1 C0 BT
137	    BLOCK_TYPE_OS_4     = 8'h2d, // D7 D6 D5 O4 C3 C2 C1 C0 BT
138	    BLOCK_TYPE_START_4  = 8'h33, // D7 D6 D5    C3 C2 C1 C0 BT
139	    BLOCK_TYPE_OS_START = 8'h66, // D7 D6 D5    O0 D3 D2 D1 BT
140	    BLOCK_TYPE_OS_04    = 8'h55, // D7 D6 D5 O4 O0 D3 D2 D1 BT
141	    BLOCK_TYPE_START_0  = 8'h78, // D7 D6 D5 D4 D3 D2 D1    BT
142	    BLOCK_TYPE_OS_0     = 8'h4b, // C7 C6 C5 C4 O0 D3 D2 D1 BT
143	    BLOCK_TYPE_TERM_0   = 8'h87, // C7 C6 C5 C4 C3 C2 C1    BT
144	    BLOCK_TYPE_TERM_1   = 8'h99, // C7 C6 C5 C4 C3 C2    D0 BT
145	    BLOCK_TYPE_TERM_2   = 8'haa, // C7 C6 C5 C4 C3    D1 D0 BT
146	    BLOCK_TYPE_TERM_3   = 8'hb4, // C7 C6 C5 C4    D2 D1 D0 BT
147	    BLOCK_TYPE_TERM_4   = 8'hcc, // C7 C6 C5    D3 D2 D1 D0 BT
148	    BLOCK_TYPE_TERM_5   = 8'hd2, // C7 C6    D4 D3 D2 D1 D0 BT
149	    BLOCK_TYPE_TERM_6   = 8'he1, // C7    D5 D4 D3 D2 D1 D0 BT
150	    BLOCK_TYPE_TERM_7   = 8'hff; //    D6 D5 D4 D3 D2 D1 D0 BT
151	
152	localparam [3:0]
153	    OUTPUT_TYPE_IDLE = 4'd0,
154	    OUTPUT_TYPE_ERROR = 4'd1,
155	    OUTPUT_TYPE_START_0 = 4'd2,
156	    OUTPUT_TYPE_START_4 = 4'd3,
157	    OUTPUT_TYPE_DATA = 4'd4,
158	    OUTPUT_TYPE_TERM_0 = 4'd8,
159	    OUTPUT_TYPE_TERM_1 = 4'd9,
160	    OUTPUT_TYPE_TERM_2 = 4'd10,
161	    OUTPUT_TYPE_TERM_3 = 4'd11,
162	    OUTPUT_TYPE_TERM_4 = 4'd12,
163	    OUTPUT_TYPE_TERM_5 = 4'd13,
164	    OUTPUT_TYPE_TERM_6 = 4'd14,
165	    OUTPUT_TYPE_TERM_7 = 4'd15;
166	
167	localparam [2:0]
168	    STATE_IDLE = 3'd0,
169	    STATE_PAYLOAD = 3'd1,
170	    STATE_PAD = 3'd2,
171	    STATE_FCS_1 = 3'd3,
172	    STATE_FCS_2 = 3'd4,
173	    STATE_ERR = 3'd5,
174	    STATE_IFG = 3'd6;
175	
176	reg [2:0] state_reg = STATE_IDLE, state_next;
177	
178	// datapath control signals
179	reg reset_crc;
180	reg update_crc;
181	
182	reg swap_lanes_reg = 1'b0, swap_lanes_next;
183	reg [31:0] swap_data = 32'd0;
184	
185	reg delay_type_valid = 1'b0;
186	reg [3:0] delay_type = OUTPUT_TYPE_IDLE;
187	
188	reg [DATA_WIDTH-1:0] s_axis_tdata_masked;
189	
190	reg [DATA_WIDTH-1:0] s_tdata_reg = 0, s_tdata_next;
191	reg [EMPTY_WIDTH-1:0] s_empty_reg = 0, s_empty_next;
192	
193	reg [DATA_WIDTH-1:0] fcs_output_data_0;
194	reg [DATA_WIDTH-1:0] fcs_output_data_1;
195	reg [3:0] fcs_output_type_0;
196	reg [3:0] fcs_output_type_1;
197	
198	reg [7:0] ifg_offset;
199	
200	reg frame_start_reg = 1'b0, frame_start_next;
201	reg frame_reg = 1'b0, frame_next;
202	reg frame_error_reg = 1'b0, frame_error_next;
203	reg [MIN_LEN_WIDTH-1:0] frame_min_count_reg = 0, frame_min_count_next;
204	
205	reg [7:0] ifg_count_reg = 8'd0, ifg_count_next;
206	reg [1:0] deficit_idle_count_reg = 2'd0, deficit_idle_count_next;
207	
208	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
209	
210	reg [PTP_TS_WIDTH-1:0] m_axis_ptp_ts_reg = 0;
211	reg [PTP_TS_WIDTH-1:0] m_axis_ptp_ts_adj_reg = 0;
212	reg [PTP_TAG_WIDTH-1:0] m_axis_ptp_ts_tag_reg = 0;
213	reg m_axis_ptp_ts_valid_reg = 1'b0;
214	reg m_axis_ptp_ts_valid_int_reg = 1'b0;
215	reg m_axis_ptp_ts_borrow_reg = 1'b0;
216	
217	reg [31:0] crc_state_reg[7:0];
218	wire [31:0] crc_state_next[7:0];
219	
220	reg [DATA_WIDTH-1:0] encoded_tx_data_reg = {{8{CTRL_IDLE}}, BLOCK_TYPE_CTRL};
221	reg [HDR_WIDTH-1:0] encoded_tx_hdr_reg = SYNC_CTRL;
222	
223	reg [DATA_WIDTH-1:0] output_data_reg = {DATA_WIDTH{1'b0}}, output_data_next;
224	reg [3:0] output_type_reg = OUTPUT_TYPE_IDLE, output_type_next;
225	
226	reg [1:0] start_packet_reg = 2'b00;
227	reg error_underflow_reg = 1'b0, error_underflow_next;
228	
229	reg [4+16-1:0] last_ts_reg = 0;
230	reg [4+16-1:0] ts_inc_reg = 0;
231	
232	assign s_axis_tready = s_axis_tready_reg;
233	
234	assign encoded_tx_data = encoded_tx_data_reg;
235	assign encoded_tx_hdr = encoded_tx_hdr_reg;
236	
237	assign m_axis_ptp_ts = PTP_TS_ENABLE ? ((!PTP_TS_FMT_TOD || m_axis_ptp_ts_borrow_reg) ? m_axis_ptp_ts_reg : m_axis_ptp_ts_adj_reg) : 0;
238	assign m_axis_ptp_ts_tag = PTP_TAG_ENABLE ? m_axis_ptp_ts_tag_reg : 0;
239	assign m_axis_ptp_ts_valid = PTP_TS_ENABLE || PTP_TAG_ENABLE ? m_axis_ptp_ts_valid_reg : 1'b0;
240	
241	assign start_packet = start_packet_reg;
242	assign error_underflow = error_underflow_reg;
243	
244	generate
245	    genvar n;
246	
247	    for (n = 0; n < 8; n = n + 1) begin : crc
248	        lfsr #(
249	            .LFSR_WIDTH(32),
250	            .LFSR_POLY(32'h4c11db7),
251	            .LFSR_CONFIG("GALOIS"),
252	            .LFSR_FEED_FORWARD(0),
253	            .REVERSE(1),
254	            .DATA_WIDTH(8*(n+1)),
255	            .STYLE("AUTO")
256	        )
257	        eth_crc (
258	            .data_in(s_tdata_reg[0 +: 8*(n+1)]),
259	            .state_in(crc_state_reg[7]),
260	            .data_out(),
261	            .state_out(crc_state_next[n])
262	        );
263	    end
264	
265	endgenerate
266	
267	function [2:0] keep2empty;
268	    input [7:0] k;
269	    casez (k)
270	        8'bzzzzzzz0: keep2empty = 3'd7;
271	        8'bzzzzzz01: keep2empty = 3'd7;
272	        8'bzzzzz011: keep2empty = 3'd6;
273	        8'bzzzz0111: keep2empty = 3'd5;
274	        8'bzzz01111: keep2empty = 3'd4;
275	        8'bzz011111: keep2empty = 3'd3;
276	        8'bz0111111: keep2empty = 3'd2;
277	        8'b01111111: keep2empty = 3'd1;
278	        8'b11111111: keep2empty = 3'd0;
279	    endcase
280	endfunction
281	
282	// Mask input data
283	integer j;
284	
285	always @* begin
286	    for (j = 0; j < 8; j = j + 1) begin
287	        s_axis_tdata_masked[j*8 +: 8] = s_axis_tkeep[j] ? s_axis_tdata[j*8 +: 8] : 8'd0;
288	    end
289	end
290	
291	// FCS cycle calculation
292	always @* begin
293	    casez (s_empty_reg)
294	        3'd7: begin
295	            fcs_output_data_0 = {24'd0, ~crc_state_next[0][31:0], s_tdata_reg[7:0]};
296	            fcs_output_data_1 = 64'd0;
297	            fcs_output_type_0 = OUTPUT_TYPE_TERM_5;
298	            fcs_output_type_1 = OUTPUT_TYPE_IDLE;
299	            ifg_offset = 8'd3;
300	        end
301	        3'd6: begin
302	            fcs_output_data_0 = {16'd0, ~crc_state_next[1][31:0], s_tdata_reg[15:0]};
303	            fcs_output_data_1 = 64'd0;
304	            fcs_output_type_0 = OUTPUT_TYPE_TERM_6;
305	            fcs_output_type_1 = OUTPUT_TYPE_IDLE;
306	            ifg_offset = 8'd2;
307	        end
308	        3'd5: begin
309	            fcs_output_data_0 = {8'd0, ~crc_state_next[2][31:0], s_tdata_reg[23:0]};
310	            fcs_output_data_1 = 64'd0;
311	            fcs_output_type_0 = OUTPUT_TYPE_TERM_7;
312	            fcs_output_type_1 = OUTPUT_TYPE_IDLE;
313	            ifg_offset = 8'd1;
314	        end
315	        3'd4: begin
316	            fcs_output_data_0 = {~crc_state_next[3][31:0], s_tdata_reg[31:0]};
317	            fcs_output_data_1 = 64'd0;
318	            fcs_output_type_0 = OUTPUT_TYPE_DATA;
319	            fcs_output_type_1 = OUTPUT_TYPE_TERM_0;
320	            ifg_offset = 8'd8;
321	        end
322	        3'd3: begin
323	            fcs_output_data_0 = {~crc_state_next[4][23:0], s_tdata_reg[39:0]};
324	            fcs_output_data_1 = {56'd0, ~crc_state_reg[4][31:24]};
325	            fcs_output_type_0 = OUTPUT_TYPE_DATA;
326	            fcs_output_type_1 = OUTPUT_TYPE_TERM_1;
327	            ifg_offset = 8'd7;
328	        end
329	        3'd2: begin
330	            fcs_output_data_0 = {~crc_state_next[5][15:0], s_tdata_reg[47:0]};
331	            fcs_output_data_1 = {48'd0, ~crc_state_reg[5][31:16]};
332	            fcs_output_type_0 = OUTPUT_TYPE_DATA;
333	            fcs_output_type_1 = OUTPUT_TYPE_TERM_2;
334	            ifg_offset = 8'd6;
335	        end
336	        3'd1: begin
337	            fcs_output_data_0 = {~crc_state_next[6][7:0], s_tdata_reg[55:0]};
338	            fcs_output_data_1 = {40'd0, ~crc_state_reg[6][31:8]};
339	            fcs_output_type_0 = OUTPUT_TYPE_DATA;
340	            fcs_output_type_1 = OUTPUT_TYPE_TERM_3;
341	            ifg_offset = 8'd5;
342	        end
343	        3'd0: begin
344	            fcs_output_data_0 = s_tdata_reg;
345	            fcs_output_data_1 = {32'd0, ~crc_state_reg[7][31:0]};
346	            fcs_output_type_0 = OUTPUT_TYPE_DATA;
347	            fcs_output_type_1 = OUTPUT_TYPE_TERM_4;
348	            ifg_offset = 8'd4;
349	        end
350	    endcase
351	end
352	
353	always @* begin
354	    state_next = STATE_IDLE;
355	
356	    reset_crc = 1'b0;
357	    update_crc = 1'b0;
358	
359	    swap_lanes_next = swap_lanes_reg;
360	
361	    frame_start_next = 1'b0;
362	    frame_next = frame_reg;
363	    frame_error_next = frame_error_reg;
364	    frame_min_count_next = frame_min_count_reg;
365	
366	    ifg_count_next = ifg_count_reg;
367	    deficit_idle_count_next = deficit_idle_count_reg;
368	
369	    s_axis_tready_next = 1'b0;
370	
371	    s_tdata_next = s_tdata_reg;
372	    s_empty_next = s_empty_reg;
373	
374	    output_data_next = s_tdata_reg;
375	    output_type_next = OUTPUT_TYPE_IDLE;
376	
377	    error_underflow_next = 1'b0;
378	
379	    if (s_axis_tvalid && s_axis_tready) begin
380	        frame_next = !s_axis_tlast;
381	    end
382	
383	    case (state_reg)
384	        STATE_IDLE: begin
385	            // idle state - wait for data
386	            frame_error_next = 1'b0;
387	            frame_min_count_next = MIN_FRAME_LENGTH-4-KEEP_WIDTH;
388	            reset_crc = 1'b1;
389	            s_axis_tready_next = 1'b1;
390	
391	            output_data_next = s_tdata_reg;
392	            output_type_next = OUTPUT_TYPE_IDLE;
393	
394	            s_tdata_next = s_axis_tdata_masked;
395	            s_empty_next = keep2empty(s_axis_tkeep);
396	
397	            if (s_axis_tvalid && cfg_tx_enable) begin
398	                // Preamble and SFD
399	                output_data_next = {ETH_SFD, {7{ETH_PRE}}};
400	                output_type_next = OUTPUT_TYPE_START_0;
401	                frame_start_next = 1'b1;
402	                s_axis_tready_next = 1'b1;
403	                state_next = STATE_PAYLOAD;
404	            end else begin
405	                swap_lanes_next = 1'b0;
406	                ifg_count_next = 8'd0;
407	                deficit_idle_count_next = 2'd0;
408	                state_next = STATE_IDLE;
409	            end
410	        end
411	        STATE_PAYLOAD: begin
412	            // transfer payload
413	            update_crc = 1'b1;
414	            s_axis_tready_next = 1'b1;
415	
416	            if (frame_min_count_reg > KEEP_WIDTH) begin
417	                frame_min_count_next = frame_min_count_reg - KEEP_WIDTH;
418	            end else begin
419	                frame_min_count_next = 0;
420	            end
421	
422	            output_data_next = s_tdata_reg;
423	            output_type_next = OUTPUT_TYPE_DATA;
424	
425	            s_tdata_next = s_axis_tdata_masked;
426	            s_empty_next = keep2empty(s_axis_tkeep);
427	
428	            if (!s_axis_tvalid || s_axis_tlast) begin
429	                s_axis_tready_next = frame_next; // drop frame
430	                frame_error_next = !s_axis_tvalid || s_axis_tuser[0];
431	                error_underflow_next = !s_axis_tvalid;
432	
433	                if (ENABLE_PADDING && frame_min_count_reg) begin
434	                    if (frame_min_count_reg > KEEP_WIDTH) begin
435	                        s_empty_next = 0;
436	                        state_next = STATE_PAD;
437	                    end else begin
438	                        if (keep2empty(s_axis_tkeep) > KEEP_WIDTH-frame_min_count_reg) begin
439	                            s_empty_next = KEEP_WIDTH-frame_min_count_reg;
440	                        end
441	                        if (frame_error_next) begin
442	                            state_next = STATE_ERR;
443	                        end else begin
444	                            state_next = STATE_FCS_1;
445	                        end
446	                    end
447	                end else begin
448	                    if (frame_error_next) begin
449	                        state_next = STATE_ERR;
450	                    end else begin
451	                        state_next = STATE_FCS_1;
452	                    end
453	                end
454	            end else begin
455	                state_next = STATE_PAYLOAD;
456	            end
457	        end
458	        STATE_PAD: begin
459	            // pad frame to MIN_FRAME_LENGTH
460	            s_axis_tready_next = frame_next; // drop frame
461	
462	            output_data_next = s_tdata_reg;
463	            output_type_next = OUTPUT_TYPE_DATA;
464	
465	            s_tdata_next = 64'd0;
466	            s_empty_next = 0;
467	
468	            update_crc = 1'b1;
469	
470	            if (frame_min_count_reg > KEEP_WIDTH) begin
471	                frame_min_count_next = frame_min_count_reg - KEEP_WIDTH;
472	                state_next = STATE_PAD;
473	            end else begin
474	                frame_min_count_next = 0;
475	                s_empty_next = KEEP_WIDTH-frame_min_count_reg;
476	                if (frame_error_reg) begin
477	                    state_next = STATE_ERR;
478	                end else begin
479	                    state_next = STATE_FCS_1;
480	                end
481	            end
482	        end
483	        STATE_FCS_1: begin
484	            // last cycle
485	            s_axis_tready_next = frame_next; // drop frame
486	
487	            output_data_next = fcs_output_data_0;
488	            output_type_next = fcs_output_type_0;
489	
490	            update_crc = 1'b1;
491	
492	            ifg_count_next = (cfg_ifg > 8'd12 ? cfg_ifg : 8'd12) - ifg_offset + (swap_lanes_reg ? 8'd4 : 8'd0) + deficit_idle_count_reg;
493	            if (s_empty_reg <= 4) begin
494	                state_next = STATE_FCS_2;
495	            end else begin
496	                state_next = STATE_IFG;
497	            end
498	        end
499	        STATE_FCS_2: begin
500	            // last cycle
501	            s_axis_tready_next = frame_next; // drop frame
502	
503	            output_data_next = fcs_output_data_1;
504	            output_type_next = fcs_output_type_1;
505	
506	            reset_crc = 1'b1;
507	
508	            if (ENABLE_DIC) begin
509	                if (ifg_count_next > 8'd7) begin
510	                    state_next = STATE_IFG;
511	                end else begin
512	                    if (ifg_count_next >= 8'd4) begin
513	                        deficit_idle_count_next = ifg_count_next - 8'd4;
514	                        swap_lanes_next = 1'b1;
515	                    end else begin
516	                        deficit_idle_count_next = ifg_count_next;
517	                        ifg_count_next = 8'd0;
518	                        swap_lanes_next = 1'b0;
519	                    end
520	                    s_axis_tready_next = 1'b1;
521	                    state_next = STATE_IDLE;
522	                end
523	            end else begin
524	                if (ifg_count_next > 8'd4) begin
525	                    state_next = STATE_IFG;
526	                end else begin
527	                    s_axis_tready_next = 1'b1;
528	                    swap_lanes_next = ifg_count_next != 0;
529	                    state_next = STATE_IDLE;
530	                end
531	            end
532	        end
533	        STATE_ERR: begin
534	            // terminate packet with error
535	            s_axis_tready_next = frame_next; // drop frame
536	
537	            output_data_next = s_tdata_reg;
538	            output_type_next = OUTPUT_TYPE_ERROR;
539	
540	            ifg_count_next = 8'd12;
541	
542	            state_next = STATE_IFG;
543	        end
544	        STATE_IFG: begin
545	            // send IFG
546	            s_axis_tready_next = frame_next; // drop frame
547	
548	            output_data_next = s_tdata_reg;
549	            output_type_next = OUTPUT_TYPE_IDLE;
550	
551	            if (ifg_count_reg > 8'd8) begin
552	                ifg_count_next = ifg_count_reg - 8'd8;
553	            end else begin
554	                ifg_count_next = 8'd0;
555	            end
556	
557	            reset_crc = 1'b1;
558	
559	            if (ENABLE_DIC) begin
560	                if (ifg_count_next > 8'd7 || frame_reg) begin
561	                    state_next = STATE_IFG;
562	                end else begin
563	                    if (ifg_count_next >= 8'd4) begin
564	                        deficit_idle_count_next = ifg_count_next - 8'd4;
565	                        swap_lanes_next = 1'b1;
566	                    end else begin
567	                        deficit_idle_count_next = ifg_count_next;
568	                        ifg_count_next = 8'd0;
569	                        swap_lanes_next = 1'b0;
570	                    end
571	                    s_axis_tready_next = 1'b1;
572	                    state_next = STATE_IDLE;
573	                end
574	            end else begin
575	                if (ifg_count_next > 8'd4 || frame_reg) begin
576	                    state_next = STATE_IFG;
577	                end else begin
578	                    s_axis_tready_next = 1'b1;
579	                    swap_lanes_next = ifg_count_next != 0;
580	                    state_next = STATE_IDLE;
581	                end
582	            end
583	        end
584	    endcase
585	end
586	
587	always @(posedge clk) begin
588	    state_reg <= state_next;
589	
590	    swap_lanes_reg <= swap_lanes_next;
591	
592	    frame_start_reg <= frame_start_next;
593	    frame_reg <= frame_next;
594	    frame_error_reg <= frame_error_next;
595	    frame_min_count_reg <= frame_min_count_next;
596	
597	    ifg_count_reg <= ifg_count_next;
598	    deficit_idle_count_reg <= deficit_idle_count_next;
599	
600	    s_tdata_reg <= s_tdata_next;
601	    s_empty_reg <= s_empty_next;
602	
603	    s_axis_tready_reg <= s_axis_tready_next;
604	
605	    m_axis_ptp_ts_valid_reg <= 1'b0;
606	    m_axis_ptp_ts_valid_int_reg <= 1'b0;
607	
608	    start_packet_reg <= 2'b00;
609	    error_underflow_reg <= error_underflow_next;
610	
611	    delay_type_valid <= 1'b0;
612	    delay_type <= output_type_next ^ 4'd4;
613	
614	    swap_data <= output_data_next[63:32];
615	
616	    if (swap_lanes_reg) begin
617	        output_data_reg <= {output_data_next[31:0], swap_data};
618	        if (delay_type_valid) begin
619	            output_type_reg <= delay_type;
620	        end else if (output_type_next == OUTPUT_TYPE_START_0) begin
621	            output_type_reg <= OUTPUT_TYPE_START_4;
622	        end else if (output_type_next[3]) begin
623	            // OUTPUT_TYPE_TERM_*
624	            if (output_type_next[2]) begin
625	                delay_type_valid <= 1'b1;
626	                output_type_reg <= OUTPUT_TYPE_DATA;
627	            end else begin
628	                output_type_reg <= output_type_next ^ 4'd4;
629	            end
630	        end else begin
631	            output_type_reg <= output_type_next;
632	        end
633	    end else begin
634	        output_data_reg <= output_data_next;
635	        output_type_reg <= output_type_next;
636	    end
637	
638	    if (PTP_TS_ENABLE && PTP_TS_FMT_TOD) begin
639	        m_axis_ptp_ts_valid_reg <= m_axis_ptp_ts_valid_int_reg;
640	        m_axis_ptp_ts_adj_reg[15:0] <= m_axis_ptp_ts_reg[15:0];
641	        {m_axis_ptp_ts_borrow_reg, m_axis_ptp_ts_adj_reg[45:16]} <= $signed({1'b0, m_axis_ptp_ts_reg[45:16]}) - $signed(31'd1000000000);
642	        m_axis_ptp_ts_adj_reg[47:46] <= 0;
643	        m_axis_ptp_ts_adj_reg[95:48] <= m_axis_ptp_ts_reg[95:48] + 1;
644	    end
645	
646	    if (frame_start_reg) begin
647	        if (swap_lanes_reg) begin
648	            if (PTP_TS_ENABLE) begin
649	                if (PTP_TS_FMT_TOD) begin
650	                    m_axis_ptp_ts_reg[45:0] <= ptp_ts[45:0] + (ts_inc_reg >> 1);
651	                    m_axis_ptp_ts_reg[95:48] <= ptp_ts[95:48];
652	                end else begin
653	                    m_axis_ptp_ts_reg <= ptp_ts + (ts_inc_reg >> 1);
654	                end
655	            end
656	            start_packet_reg <= 2'b10;
657	        end else begin
658	            if (PTP_TS_ENABLE) begin
659	                m_axis_ptp_ts_reg <= ptp_ts;
660	            end
661	            start_packet_reg <= 2'b01;
662	        end
663	        if (PTP_TS_ENABLE) begin
664	            if (PTP_TS_CTRL_IN_TUSER) begin
665	                m_axis_ptp_ts_tag_reg <= s_axis_tuser >> 2;
666	                if (PTP_TS_FMT_TOD) begin
667	                    m_axis_ptp_ts_valid_int_reg <= s_axis_tuser[1];
668	                end else begin
669	                    m_axis_ptp_ts_valid_reg <= s_axis_tuser[1];
670	                end
671	            end else begin
672	                m_axis_ptp_ts_tag_reg <= s_axis_tuser >> 1;
673	                if (PTP_TS_FMT_TOD) begin
674	                    m_axis_ptp_ts_valid_int_reg <= 1'b1;
675	                end else begin
676	                    m_axis_ptp_ts_valid_reg <= 1'b1;
677	                end
678	            end
679	        end
680	    end
681	
682	    case (output_type_reg)
683	        OUTPUT_TYPE_IDLE: begin
684	            encoded_tx_data_reg <= {{8{CTRL_IDLE}}, BLOCK_TYPE_CTRL};
685	            encoded_tx_hdr_reg <= SYNC_CTRL;
686	        end
687	        OUTPUT_TYPE_ERROR: begin
688	            encoded_tx_data_reg <= {{8{CTRL_ERROR}}, BLOCK_TYPE_CTRL};
689	            encoded_tx_hdr_reg <= SYNC_CTRL;
690	        end
691	        OUTPUT_TYPE_START_0: begin
692	            encoded_tx_data_reg <= {output_data_reg[63:8], BLOCK_TYPE_START_0};
693	            encoded_tx_hdr_reg <= SYNC_CTRL;
694	        end
695	        OUTPUT_TYPE_START_4: begin
696	            encoded_tx_data_reg <= {output_data_reg[63:40], 4'd0, {4{CTRL_IDLE}}, BLOCK_TYPE_START_4};
697	            encoded_tx_hdr_reg <= SYNC_CTRL;
698	        end
699	        OUTPUT_TYPE_DATA: begin
700	            encoded_tx_data_reg <= output_data_reg;
701	            encoded_tx_hdr_reg <= SYNC_DATA;
702	        end
703	        OUTPUT_TYPE_TERM_0: begin
704	            encoded_tx_data_reg <= {{7{CTRL_IDLE}}, 7'd0, BLOCK_TYPE_TERM_0};
705	            encoded_tx_hdr_reg <= SYNC_CTRL;
706	        end
707	        OUTPUT_TYPE_TERM_1: begin
708	            encoded_tx_data_reg <= {{6{CTRL_IDLE}}, 6'd0, output_data_reg[7:0], BLOCK_TYPE_TERM_1};
709	            encoded_tx_hdr_reg <= SYNC_CTRL;
710	        end
711	        OUTPUT_TYPE_TERM_2: begin
712	            encoded_tx_data_reg <= {{5{CTRL_IDLE}}, 5'd0, output_data_reg[15:0], BLOCK_TYPE_TERM_2};
713	            encoded_tx_hdr_reg <= SYNC_CTRL;
714	        end
715	        OUTPUT_TYPE_TERM_3: begin
716	            encoded_tx_data_reg <= {{4{CTRL_IDLE}}, 4'd0, output_data_reg[23:0], BLOCK_TYPE_TERM_3};
717	            encoded_tx_hdr_reg <= SYNC_CTRL;
718	        end
719	        OUTPUT_TYPE_TERM_4: begin
720	            encoded_tx_data_reg <= {{3{CTRL_IDLE}}, 3'd0, output_data_reg[31:0], BLOCK_TYPE_TERM_4};
721	            encoded_tx_hdr_reg <= SYNC_CTRL;
722	        end
723	        OUTPUT_TYPE_TERM_5: begin
724	            encoded_tx_data_reg <= {{2{CTRL_IDLE}}, 2'd0, output_data_reg[39:0], BLOCK_TYPE_TERM_5};
725	            encoded_tx_hdr_reg <= SYNC_CTRL;
726	        end
727	        OUTPUT_TYPE_TERM_6: begin
728	            encoded_tx_data_reg <= {{1{CTRL_IDLE}}, 1'd0, output_data_reg[47:0], BLOCK_TYPE_TERM_6};
729	            encoded_tx_hdr_reg <= SYNC_CTRL;
730	        end
731	        OUTPUT_TYPE_TERM_7: begin
732	            encoded_tx_data_reg <= {output_data_reg[55:0], BLOCK_TYPE_TERM_7};
733	            encoded_tx_hdr_reg <= SYNC_CTRL;
734	        end
735	        default: begin
736	            encoded_tx_data_reg <= {{8{CTRL_ERROR}}, BLOCK_TYPE_CTRL};
737	            encoded_tx_hdr_reg <= SYNC_CTRL;
738	        end
739	    endcase
740	
741	    crc_state_reg[0] <= crc_state_next[0];
742	    crc_state_reg[1] <= crc_state_next[1];
743	    crc_state_reg[2] <= crc_state_next[2];
744	    crc_state_reg[3] <= crc_state_next[3];
745	    crc_state_reg[4] <= crc_state_next[4];
746	    crc_state_reg[5] <= crc_state_next[5];
747	    crc_state_reg[6] <= crc_state_next[6];
748	
749	    if (update_crc) begin
750	        crc_state_reg[7] <= crc_state_next[7];
751	    end
752	
753	    if (reset_crc) begin
754	        crc_state_reg[7] <= 32'hFFFFFFFF;
755	    end
756	
757	    last_ts_reg <= ptp_ts;
758	    ts_inc_reg <= ptp_ts - last_ts_reg;
759	
760	    if (rst) begin
761	        state_reg <= STATE_IDLE;
762	
763	        frame_start_reg <= 1'b0;
764	        frame_reg <= 1'b0;
765	
766	        swap_lanes_reg <= 1'b0;
767	
768	        ifg_count_reg <= 8'd0;
769	        deficit_idle_count_reg <= 2'd0;
770	
771	        s_axis_tready_reg <= 1'b0;
772	
773	        m_axis_ptp_ts_valid_reg <= 1'b0;
774	        m_axis_ptp_ts_valid_int_reg <= 1'b0;
775	
776	        encoded_tx_data_reg <= {{8{CTRL_IDLE}}, BLOCK_TYPE_CTRL};
777	        encoded_tx_hdr_reg <= SYNC_CTRL;
778	
779	        output_data_reg <= {DATA_WIDTH{1'b0}};
780	        output_type_reg <= OUTPUT_TYPE_IDLE;
781	
782	        start_packet_reg <= 2'b00;
783	        error_underflow_reg <= 1'b0;
784	
785	        delay_type_valid <= 1'b0;
786	        delay_type <= OUTPUT_TYPE_IDLE;
787	    end
788	end
789	
790	endmodule
791	
792	`resetall
